// Build CSV per regulator schema (UKGC LCCP example)
const ledger = $node['Ledger 24h'].json;
const kyc = $node['KYC counts 24h'].json;
const cases = $node['Case Mgmt 24h'].json;
const date = ledger.report_date;
const rows = [
  ['report_date', 'metric', 'value'],
  [date, 'deposits_count', ledger.deposits_count],
  [date, 'deposits_total_eur', ledger.deposits_total],
  [date, 'withdrawals_count', ledger.withdrawals_count],
  [date, 'withdrawals_total_eur', ledger.withdrawals_total],
  [date, 'bets_count', ledger.bets_count],
  [date, 'bets_total_eur', ledger.bets_total],
  [date, 'wins_count', ledger.wins_count],
  [date, 'wins_total_eur', ledger.wins_total],
  ...kyc.map(k => [date, `kyc_${k.kyc_status}`, k.n]),
  ...cases.map(c => [date, `case_${c.type}_${c.status}`, c.n]),
];
const csv = rows.map(r => r.map(v => String(v).includes(',') ? `"${v}"` : v).join(',')).join('\n');
return [{ json: { report_date: date, csv, filename: `compliance-${date}.csv` }, binary: { data: { data: Buffer.from(csv).toString('base64'), mimeType: 'text/csv', fileName: `compliance-${date}.csv` } } }];
